        [Fact]
        public async Task AnalyzeSyncDeltasAsync_ShouldDetectColorMismatch()
        {
            _outlookProviderMock.Setup(p => p.GetAllCategories())
                .Returns(new List<(string, string?)> { ("SharedCat", "#OUTLOOK") });

            var dbCategories = new List<CategoryNode> { new CategoryNode("SharedCat", "#DBCOLOR") };
            _categoryRepositoryMock.Setup(r => r.GetAllAsync(It.IsAny<bool>())).ReturnsAsync(dbCategories);

            var result = await _sut.AnalyzeSyncDeltasAsync();

            Assert.True(result.HasConflicts);
            Assert.Single(result.GetColorConflicts());
            
            var conflict = result.GetColorConflicts().First();
            Assert.Equal("SharedCat", conflict.CategoryName);
            Assert.Equal("#OUTLOOK", conflict.OutlookColor);
            Assert.Equal("#DBCOLOR", conflict.CatamailerColor);
        }

        [Fact]
        public async Task AnalyzeSyncDeltasAsync_ShouldDetectColorMismatch_WhenOutlookLacksInheritedColor()
        {
            // Arrange
            _outlookProviderMock.Setup(p => p.GetAllCategories())
                .Returns(new List<(string, string?)> 
                { 
                    ("Parent", "#FF0000"),
                    ("Parent-Child", null) // Outlook n'a pas la couleur explicitement
                });

            var parent = new CategoryNode("Parent", "#FF0000");
            var child = new CategoryNode("Child", null);
            parent.AddChild(child); // EffectiveColor de l'enfant devient #FF0000
            
            _categoryRepositoryMock.Setup(r => r.GetAllAsync(It.IsAny<bool>())).ReturnsAsync(new List<CategoryNode> { parent, child });

            // Act
            var result = await _sut.AnalyzeSyncDeltasAsync("-");

            // Assert
            Assert.True(result.HasConflicts);
            var mismatches = result.GetColorConflicts().ToList();
            
            // Actuellement le test va échouer car Catamailer simule l'héritage pour Outlook (faux-positif de Synchronized)
            Assert.Single(mismatches);
            Assert.Equal("Parent-Child", mismatches[0].CategoryName);
            Assert.Equal("", mismatches[0].OutlookColor);
            Assert.Equal("#FF0000", mismatches[0].CatamailerColor);
        }

        [Fact]
        public async Task AnalyzeSyncDeltasAsync_ShouldCreateImplicitParent_WhenOnlyChildExistsInOutlook()
        {
            _outlookProviderMock.Setup(p => p.GetAllCategories())
                .Returns(new List<(string, string?)> { ("CCOEN-Voyage", "#1ABC9C") });

            _categoryRepositoryMock.Setup(r => r.GetAllAsync(It.IsAny<bool>())).ReturnsAsync(new List<CategoryNode>());

            var result = await _sut.AnalyzeSyncDeltasAsync("-");

            Assert.True(result.HasConflicts);
            var missing = result.GetMissingInCatamailer().ToList();
            
            Assert.Equal(2, missing.Count);
            
            var parentDelta = missing.FirstOrDefault(m => m.CategoryName == "CCOEN");
            Assert.NotNull(parentDelta);
            Assert.Equal("#1ABC9C", parentDelta.OutlookColor);
            Assert.Equal("#1ABC9C", parentDelta.OptimizedColor);
            Assert.True(parentDelta.IsImplicit);

            var childDelta = missing.FirstOrDefault(m => m.CategoryName == "CCOEN-Voyage");
            Assert.NotNull(childDelta);
            Assert.Equal("#1ABC9C", childDelta.OutlookColor);
            Assert.Null(childDelta.OptimizedColor); 
            Assert.False(childDelta.IsImplicit);
        }

