        [Fact]
        public async Task AnalyzeSyncDeltasAsync_ShouldBubbleUpColorToImplicitParents_WhenAllChildrenShareSameColor()
        {
            _outlookProviderMock.Setup(p => p.GetAllCategories())
                .Returns(new List<(string, string?)> 
                { 
                    ("DAMSI-DA-AE-EAEA", "#800000"),
                    ("DAMSI-DA-AE-Equipiers", "#800000") 
                });

            _categoryRepositoryMock.Setup(r => r.GetAllAsync(It.IsAny<bool>())).ReturnsAsync(new List<CategoryNode>());

            var result = await _sut.AnalyzeSyncDeltasAsync("-");

            var missing = result.GetMissingInCatamailer().ToList();
            Assert.Equal(5, missing.Count);

            var damsi = missing.First(m => m.CategoryName == "DAMSI");
            Assert.Equal("#800000", damsi.OutlookColor);
            Assert.Equal("#800000", damsi.OptimizedColor);
            Assert.True(damsi.IsImplicit); 

            var eaea = missing.First(m => m.CategoryName == "DAMSI-DA-AE-EAEA");
            Assert.False(eaea.IsImplicit); 
        }

        [Fact]
        public async Task AnalyzeSyncDeltasAsync_ShouldTrimSpacesAroundSeparator_ToGroupCorrectly()
        {
            _outlookProviderMock.Setup(p => p.GetAllCategories())
                .Returns(new List<(string, string?)> 
                { 
                    ("Cercle A", "#0000FF"),
                    ("Cercle A - PAG", "#0000FF") 
                });

            _categoryRepositoryMock.Setup(r => r.GetAllAsync(It.IsAny<bool>())).ReturnsAsync(new List<CategoryNode>());

            var result = await _sut.AnalyzeSyncDeltasAsync("-");

            var missing = result.GetMissingInCatamailer().ToList();
            
            Assert.Equal(2, missing.Count);
            Assert.Contains(missing, m => m.CategoryName == "Cercle A");
            
            var child = missing.FirstOrDefault(m => m.CategoryName == "Cercle A - PAG");
            Assert.NotNull(child);
            Assert.Null(child.OptimizedColor); 
        }

        [Fact]
        public async Task AnalyzeSyncDeltasAsync_ShouldUseFullName_WhenPushingToOutlook()
        {
